# Description

This PR modifies the ready event from this bot and adds changing status functionality every 5 hours, you may change the `presences` array declared in the top level of the module to change what status and status type will be shown.

```ts
const presences: ActivityOptions[] = [
	{ name: "your SaaS projects", type: ActivityType.Watching },
	{ name: "for your contributions", type: ActivityType.Listening },
	{ name: "with your SaaS project", type: ActivityType.Playing }
];
```

intends to solve #12

## Problem:

Deno loading cjs file instead of esm module.
 
<details><summary>Сode with incorrect behavior</summary>
<p>

```typescript
#!/usr/bin/env -S deno run -Ar --watch

import {zValidator} from 'npm:@hono/zod-validator'
import {Hono} from 'npm:hono'
import {z} from 'npm:zod'

const app = new Hono()
const schema = z.object({val: z.string()})

app.post('/post', zValidator('form', schema), (c) => {
  return c.json(c.req.valid('form'))
})

{
  const res = await app.request('/post', {
    method: 'POST',
    headers: {'content-type': 'application/json'},
    body: JSON.stringify({val: 'text'}), // incorrect data
  })
  console.log(res.status, res.status === 400) // expected 400
  console.log(await res.text())
}
{
  const res = await app.request('/post', {
    method: 'POST',
    headers: {'content-type': 'application/x-www-form-urlencoded'},
    body: new URLSearchParams({val: 'text'}), // valid data
  })
  console.log(res.status, res.status === 200) // expected 200
  console.log(await res.text())
}
```

</p>
</details> 

